      "targetPlatform": "Web Browser (Desktop & Mobile)",
      "primaryDomain": "E-Commerce & Digital Auctions",
      "architecturePipeline": "CodeIgniter MVC + MariaDB + OAuth/SMTP",
      "testingAndAudit": "Passed",
