    "userFlow": {
      "summary": "Users authenticate into an organization workspace, configure master items and warehouse locations, and execute procurement, production, or stock opname workflows. Every stock-affecting action routes through the central posting engine, updating balances, ledger entries, valuation, and alerts atomically.",
      "steps": [
        {
          "step": "01",
          "title": "Workspace Registration & Authentication",
          "description": "Users register an organization (provisioning default UOMs, Free plan, and initial warehouse bins) or sign into an existing tenant via httpOnly JWT cookies.",
          "actorOrNode": "Auth Service / Session Context"
        },
        {
          "step": "02",
          "title": "Master Data & Opening Stock Setup",
          "description": "Managers define SKUs, storage locations, UOM conversions, suppliers, and customers manually or via validated CSV bulk imports.",
          "actorOrNode": "Master Data / CSV Import Workbench"
        },
        {
          "step": "03",
          "title": "Procurement & Inbound Receiving",
          "description": "Purchase orders progress through approval and partial or full receiving, posting RECEIPT transactions that recalculate moving average item costs.",
          "actorOrNode": "Purchase Service / Inventory Engine"
        },
        {
          "step": "04",
          "title": "BOM Manufacturing & Scrap Tracking",
          "description": "Work order confirmation reserves raw materials; operators post actual material consumption, finished outputs, and closed-loop SCRAP_IN records.",
          "actorOrNode": "Production & Scrap Services"
        },
        {
          "step": "05",
          "title": "Physical Opname & Ledger Reporting",
          "description": "Warehouse teams reconcile physical counts against live balances via ADJUSTMENT postings and inspect immutable ledger, valuation, and audit reports.",
          "actorOrNode": "Opname Service / Analytics Reports"
        }
      ]
    },
    "systemArchitecture": {
      "summary": "The application follows a modular Next.js App Router architecture pairing React client consoles with Zod-validated REST API routes and domain service modules. All stock mutations serialize through a posting mutex and Prisma database transactions over an append-only ledger and reconciled balance tables.",
      "layers": [
        {
          "name": "Presentation & Client Console Layer",
          "role": "Renders role-filtered navigation, KPI dashboards, operational forms, modals, and CSV export triggers.",
          "components": [
            "Next.js App Router Pages",
            "AppShell Sidebar",
            "Operational Form Components",
            "Toast Notification Provider"
          ]
        },
        {
          "name": "API Gateway & Security Layer",
          "role": "Enforces HS256 JWT cookie verification, 24-permission RBAC checks, subscription operational gates, and Zod payload validation.",
          "components": [
            "Route Handlers (/api/**)",
            "Auth & RBAC Middleware",
            "Rate Limiter",
            "Zod Request Schemas"
          ]
        },
        {
          "name": "Domain Services & ACID Engine Layer",
          "role": "Implements purchasing, manufacturing, scrap, opname, and CSV validation workflows converging on the serialized inventory posting engine.",
          "components": [
            "ACID Inventory Engine",
            "Decimal.js Costing Module",
            "Production & BOM Service",
            "Procurement & Opname Services"
          ]
        },
        {
          "name": "Persistence & Audit Layer",
          "role": "Stores multi-tenant master data, immutable ledger journals, reconciled stock balances, reservations, alerts, and JSON audit logs.",
          "components": [
            "Prisma ORM Client",
            "SQLite / PostgreSQL Schema",
            "LedgerEntry & StockBalance",
            "AuditLog & DocCounter"
          ]
        }
      ]
    },
    "databaseDataFlow": {
      "type": "Database Schema / ERD",
      "summary": "A 24-model relational schema normalized by organizationId separates master catalogs, operational documents (PO, MO, StockCount, ScrapRecord), and the central InventoryTransaction-to-LedgerEntry-to-StockBalance accounting pipeline.",
      "entitiesOrPipelines": [
        {
          "name": "Organization & Membership",
          "type": "Table",
          "fields": [
            "id",
            "name",
            "currency",
            "status",
            "userId",
            "role",
            "subscriptionId"
          ]
        },
        {
          "name": "Item & StorageLocation",
          "type": "Table",
          "fields": [
            "id",
            "organizationId",
            "code",
            "type",
            "baseUomId",
            "avgCost",
            "minStock",
            "warehouseId"
          ]
        },
        {
          "name": "InventoryTransaction & Line",
          "type": "Table",
          "fields": [
            "id",
            "number",
            "type",
            "status",
            "idempotencyKey",
            "reversalOfId",
            "itemId",
            "locationId",
            "quantity",
            "unitCost"
          ]
        },
        {
          "name": "LedgerEntry & StockBalance",
          "type": "Table",
          "fields": [
            "transactionId",
            "entryType",
            "quantity",
            "runningQty",
            "value",
            "onHand",
            "reserved"
          ]
        },
        {
          "name": "BillOfMaterials & ProductionOrder",
          "type": "Table",
          "fields": [
            "code",
            "version",
            "outputQty",
            "number",
            "plannedQty",
            "status",
            "sourceWarehouseId"
          ]
        },
        {
          "name": "ScrapRecord & StockCount",
          "type": "Table",
          "fields": [
            "number",
            "category",
            "scrapQty",
            "status",
            "baselineQty",
            "countedQty",
            "adjustmentTransactionId"
          ]
        }
      ]
    },
    "technicalImplementation": [
      {
        "category": "Concurrency & Atomicity",
        "title": "Serialized Posting Lock & Atomic Transactions",
        "description": "Wraps every stock mutation in a promise-chain posting lock (withPostingLock) and Prisma $transaction so concurrent postings cannot read stale StockBalance rows and bypass non-negative validation.",
        "badge": "ACID Guard"
      },
      {
        "category": "Financial Precision",
        "title": "34-Digit Moving Weighted Average Engine",
        "description": "Configures Decimal.js at 34-digit precision with ROUND_HALF_UP and fixed-scale string normalization (4 dp quantities, 6 dp unit costs) to prevent rounding drift across conversions and valuations.",
        "badge": "Decimal Math"
      },
      {
        "category": "Audit & Immutability",
        "title": "Append-Only Ledger & Reversal Pattern",
        "description": "Prohibits editing posted InventoryTransaction documents; corrections generate linked REVERSAL transactions and compensating LedgerEntry rows while capturing before/after JSON diffs in AuditLog.",
        "badge": "Immutable Log"
      },
      {
        "category": "Security & Multi-Tenancy",
        "title": "Tenant Isolation, RBAC & Subscription Gate",
        "description": "Binds active organizationId inside httpOnly HS256 JWT sessions, enforces 24 granular permissions across 5 roles, rate-limits login attempts, and blocks writes for suspended subscriptions.",
        "badge": "Zero-Trust RBAC"
      }
    ],
    "primaryTechSpecs": {
      "programmingLanguage": "TypeScript",
      "framework": "Next.js",
      "database": "SQLite"
    },
    "architectureQuality": {
      "badges": [
        "ACID Ledger Engine",
        "Multi-Tenant RBAC",
        "Moving Average Costing",
        "34-Digit Precision"
      ]
    }
