    "dataAnalyticsKeyFindings": [
      {
        "metricValue": "$316.8M",
        "metricLabel": "Monthly Gross Payroll",
        "title": "Multi-Billion Annual Payroll Across Balanced Global Hubs",
        "description": "1,802 employees across 7 balanced countries (12.99%-15.65% each) generate $316.84M/month gross ($3.80B/year) and $274.15M/month net after 13.48% effective progressive deductions.",
        "impactTag": "Payroll Scale"
      },
      {
        "metricValue": "42.6%",
        "metricLabel": "Age + Tenure R-Squared",
        "title": "Seniority & Age Dominate Compensation Over Country or Role",
        "description": "Kruskal-Wallis tests show non-significant salary differences across countries (p=0.7082), departments (p=0.2401), and roles (p=0.2219), while Age (rho=+0.6802) and Tenure (rho=+0.4218) drive 42.63% of variance.",
        "impactTag": "Pay Drivers"
      },
      {
        "metricValue": "-28.1%",
        "metricLabel": "Median Gender Pay Gap",
        "title": "Significant Gender Disparity in Representation & Compensation",
        "description": "Female employees (27.69% of workforce) earn a median $119,557 vs $166,308 for males (p=1.03e-23), with a -$24,057.67/month controlled OLS residual despite near-parity (-2.68%) under age 30.",
        "impactTag": "Pay Equity"
      },
      {
        "metricValue": "52.4%",
        "metricLabel": "2017-2019 Hiring Wave",
        "title": "Concentrated Mid-Tenure Cohort & Q3 Recruitment Peak",
        "description": "945 of 1,802 active employees joined during 2017-2019 with a sharp July seasonal peak (327 hires, 18.15%), while female hiring share climbed from ~11%-15% (2006-2011) to 34.33% in 2019.",
        "impactTag": "Workforce Growth"
      },
      {
        "metricValue": "38.1%",
        "metricLabel": "Top 20% Payroll Share",
        "title": "Heavy Top-End Concentration & Unbanded Role Dispersion",
        "description": "The highest-paid 20% absorb 38.13% of gross payroll (23.15% by top 10%), while 63 IQR outliers (>$396.5K, max $1,024,965) and 6 low-end records (<$10K, min $256) expose missing role salary bands.",
        "impactTag": "Cost Risk"
      }
    ],
    "recommendationsAndConclusion": {
      "recommendations": [
        {
          "title": "Audit 69 Extreme Salary Records & Lock HRIS Master Data",
          "action": "Validate the 6 sub-$10K records and 63 IQR outliers against contracts, enforce Name_Id as primary key, trim 'Presales ' whitespace, replace TODAY() with a fixed snapshot date, and enable PivotCache auto-refresh.",
          "priority": "HIGH"
        },
        {
          "title": "Capture Job Grade & Execute Pay Equity Remediation",
          "action": "Enrich HRIS records with Job_Level and Performance_Rating to audit residual gender pay gaps, prioritizing HR (-37.38% mean), Sales and Marketing, and Germany (-33.64% mean).",
          "priority": "HIGH"
        },
        {
          "title": "Establish Formal Global Salary Bands Across 19 Roles",
          "action": "Define Min-Mid-Max USD compensation corridors by role and grade to eliminate extreme intra-role spreads and govern progression across the $3.80B annual payroll budget.",
          "priority": "STRATEGIC"
        },
        {
          "title": "Sustain Inclusive Hiring & Pre-Plan Q3 Onboarding Capacity",
          "action": "Maintain >=35% female hiring share, track promotion parity into 40+ cohorts, and align Talent Acquisition and Finance budgets in Q2 ahead of peak July hiring surges.",
          "priority": "MEDIUM"
        }
      ],
      "conclusion": "Global headcount is balanced across 7 hubs while compensation is strongly driven by age and tenure (42.63% R-squared) rather than country or role. Immediate HRIS key governance, outlier validation, role-based salary bands, and grade-controlled pay equity audits will align $3.80B annual payroll."
    },
