    "projectInfo": {
      "projectType": "Full-Stack Multi-Vendor Marketplace",
      "developmentStatus": "Completed",
      "developmentYear": "2026",
      "platform": "Web & Docker Compose",
      "projectCategory": "Web Development"
    },
    "projectBackground": "Multi-vendor marketplaces often struggle when customers purchase items from several independent stores in one cart, risking overselling, inconsistent shipping quotes, and tangled commission accounting. ShopSphere addresses this by combining a unified storefront with atomic per-vendor order splitting and ledger tracking.",
    "problemStatements": [
      {
        "title": "Concurrent Overselling on Limited Variant Stock",
        "description": "High-demand product variants can be checked out simultaneously by competing shoppers, causing negative inventory or double-sold last units without row-level database locking.",
        "issueCode": "ISSUE_01"
      },
      {
        "title": "Coupled Multi-Store Order Fulfillment",
        "description": "A single customer checkout containing items from multiple vendors cannot share one fulfillment status or shipping fee because each store packs, ships, and earns commission independently.",
        "issueCode": "ISSUE_02"
      },
      {
        "title": "Unverified Payment Callbacks & Duplicate Webhook Processing",
        "description": "Payment gateway webhooks are susceptible to replay attacks, signature spoofing, or late delivery after a checkout reservation has already expired.",
        "issueCode": "ISSUE_03"
      },
      {
        "title": "Mutable Commission & Financial Drift",
        "description": "Updating platform commission rates or issuing partial-store refunds across discounted multi-vendor orders can corrupt historical earnings unless rates and ledger entries are immutable.",
        "issueCode": "ISSUE_04"
      }
    ],
    "projectObjectives": [
      {
        "title": "Zero-Oversell Atomic Checkout Engine",
        "description": "Enforce pessimistic MySQL row locks, idempotency keys, and 30-minute stock reservations with automated background expiration so the last unit can never be sold twice.",
        "targetTag": "TARGET_01"
      },
      {
        "title": "Parent-to-Seller Order Splitting",
        "description": "Partition each cross-store checkout into one parent payment order and isolated per-store seller orders with independent shipping quotes, fulfillment state machines, and tracking numbers.",
        "targetTag": "TARGET_02"
      },
      {
        "title": "Cryptographically Verified & Idempotent Settlement",
        "description": "Authenticate payment webhooks with HMAC-SHA256 signatures, deduplicate event IDs, reject mismatched amounts, and allocate voucher discounts accurately during pre-shipment refunds.",
        "targetTag": "TARGET_03"
      },
      {
        "title": "Audited Role-Based Operations",
        "description": "Deliver dedicated Customer, Seller Center, and Admin Center portals with SHA-256 session cookies, same-origin CSRF checks, immutable seller ledger entries, and administrative audit logs.",
        "targetTag": "TARGET_04"
      }
    ],
    "coreFeatures": [
      {
        "title": "Cross-Store Catalog, Filtering & Storefronts",
        "description": "Buyers discover products across verified stores with keyword search, category counts, price bounds, rating filters, sorting, variant selection, and dedicated vendor storefront pages.",
        "badge": "Storefront"
      },
      {
        "title": "Unified Cart & Multi-Store Checkout Engine",
        "description": "Groups cart items by store, calculates per-store regular or express shipping fees, validates voucher quotas, checks expected totals, and reserves stock inside a single database transaction.",
        "badge": "Checkout"
      },
      {
        "title": "HMAC Payment Webhooks & Controlled Refunds",
        "description": "Processes sandbox payment callbacks with HMAC-SHA256 verification and idempotent event logs, while supporting full pre-shipment seller-order refunds that restore stock and recalculate parent status.",
        "badge": "Payments"
      },
      {
        "title": "Seller Center & Immutable Financial Ledger",
        "description": "Empowers verified sellers to manage products, SKUs, stock adjustments, sequential order fulfillment, CSV sales reports, and immutable SALE and COMMISSION ledger balances.",
        "badge": "Seller Portal"
      },
      {
        "title": "Admin Center & Compliance Audit Trail",
        "description": "Provides marketplace-wide GMV analytics, private store verification document downloads, user/product/review moderation, voucher and commission governance, support tickets, and audit logs.",
        "badge": "Admin Governance"
      }
    ],
