    "userFlow": {
      "summary": "Learners browse the catalog, enroll with snapshotted curriculum rules, progress through sequential lessons, complete timed quizzes and assignments, and receive verifiable PDF certificates while instructors grade submissions and admins govern platform operations.",
      "steps": [
        {
          "step": "01",
          "title": "Authentication & Role Routing",
          "description": "Users sign in or register, receiving an HttpOnly edu_session cookie and routing automatically to Student, Instructor, or Admin workspaces.",
          "actorOrNode": "AuthController / Vue Router"
        },
        {
          "step": "02",
          "title": "Course Authoring & Admin Review",
          "description": "Instructors build modules, lessons, weighted evaluations, and assignments, submitting courses for Admin review before catalog publication.",
          "actorOrNode": "CourseController / AdminController"
        },
        {
          "step": "03",
          "title": "Enrollment & Sequential Learning",
          "description": "Students enroll in published courses, locking required items and passing thresholds into enrollment snapshots while tracking lesson completion.",
          "actorOrNode": "LearningController / PostgreSQL"
        },
        {
          "step": "04",
          "title": "Timed Evaluation & Assignment Grading",
          "description": "Learners submit timed quiz attempts and versioned assignments; instructors grade subjective items and publish weighted scores.",
          "actorOrNode": "EvaluationController"
        },
        {
          "step": "05",
          "title": "Certificate Issuance & Verification",
          "description": "Meeting all required items and passing score triggers idempotent PDF certificate generation verifiable publicly via unique EDU codes.",
          "actorOrNode": "CertificateController / PDFBox"
        }
      ]
    },
    "systemArchitecture": {
      "summary": "EduSphere uses a containerized three-tier topology: a Vue 3 TypeScript SPA served by Nginx with CSP headers proxies `/api/` calls to a Java 21 Spring Boot backend, which enforces CSRF/rate-limit filters and persists data in PostgreSQL 17 and mounted private file volumes.",
      "layers": [
        {
          "name": "Client & Edge Proxy Layer",
          "role": "Renders responsive role-based SPA views, enforces route guards, sets Content Security Policy headers, and proxies `/api/` requests.",
          "components": [
            "Vue 3 SPA",
            "Vue Router",
            "Bootstrap",
            "Nginx"
          ]
        },
        {
          "name": "Security & API Gateway Layer",
          "role": "Validates `HttpOnly` session cookies, `X-EduSphere: 1` anti-CSRF headers, exact `Origin` matching, and IP auth rate limits.",
          "components": [
            "RequestGuard",
            "AuthService",
            "Domain REST Controllers"
          ]
        },
        {
          "name": "Business Logic & Scheduler Layer",
          "role": "Handles curriculum progression, evaluation grading, Tika file inspection, PDF certificate generation, attempt expiry, and deadline reminders.",
          "components": [
            "CourseService",
            "LearningService",
            "EvaluationService",
            "DeadlineReminders"
          ]
        },
        {
          "name": "Persistence & Messaging Layer",
          "role": "Stores relational state via Flyway-managed schemas, private uploaded files on Docker volumes, and transactional email via Mailpit/SMTP.",
          "components": [
            "PostgreSQL 17",
            "Flyway Migrations",
            "File Storage Volume",
            "Mailpit"
          ]
        }
      ]
    },
