    "dataAnalyticsKeyFindings": [
      {
        "metricValue": "+18.6 pp",
        "metricLabel": "Engagement Tier Lift",
        "title": "Behavioral Engagement Is the Top Conversion Driver",
        "description": "EngagementScore shows the strongest correlation (r = +0.2833, Cohen's d = +0.8978), lifting conversion from 76.45% in Low Engagement to 95.05% in High Engagement while reducing CPA from $6,494 to $5,290.",
        "impactTag": "Behavioral Intent"
      },
      {
        "metricValue": "93.36%",
        "metricLabel": "Conversion Campaign CVR",
        "title": "Conversion Campaigns Outperform All Funnel Stages",
        "description": "CampaignType = Conversion achieves 93.36% conversion and the lowest CPA ($5,312.06), exceeding Awareness (85.56%), Consideration (85.56%), and Retention (85.82%) by 7.5 to 7.8 percentage points.",
        "impactTag": "Funnel Efficiency"
      },
      {
        "metricValue": "+39.4%",
        "metricLabel": "CPA Surge Above $7.5K",
        "title": "Diminishing Returns Above $7,500 AdSpend",
        "description": "Spending above $7,500 absorbs $16.95M (42.36% of budget) yet adds only +0.24 pp conversion (92.42% vs 92.18% in $5K-$7.5K) while spiking CPA from $6,786 to $9,457.",
        "impactTag": "Budget Optimization"
      },
      {
        "metricValue": "+10.7 pp",
        "metricLabel": "Loyalty Threshold Lift",
        "title": "1,000-Point Loyalty Activation Threshold",
        "description": "Bronze customers (0-1K points) convert at 78.96% ($6,321 CPA), whereas Silver, Gold, and Platinum tiers stabilize at 89.64% to 90.26% once crossing 1,000 loyalty points.",
        "impactTag": "Customer Retention"
      },
      {
        "metricValue": "$4.01M",
        "metricLabel": "Non-Converting Spend",
        "title": "Demographic & Channel Neutrality Amid Spend Leakage",
        "description": "Channel (p = 0.594), Gender (p = 0.951), Age (p = 0.607), and Income (p = 0.645) show no significant conversion differences, while 63.56% of the 988 non-converters fall in Low Engagement.",
        "impactTag": "Targeting Precision"
      }
    ],
    "recommendationsAndConclusion": {
      "recommendations": [
        {
          "title": "Test and Enforce an AdSpend Cap at $7,500",
          "action": "Run a 30-60 day A/B holdout test capping per-customer spend at $5,000-$7,500 and reallocating excess funds from the $16.95M >$7.5K tier to reduce marginal CPA from $9,457 toward $6,786.",
          "priority": "HIGH"
        },
        {
          "title": "Prioritize Conversion Campaigns & Retargeting",
          "action": "Increase budget share for CampaignType = Conversion among engaged prospects and deploy automated retargeting flows from Awareness and Consideration audiences to push overall CPA below $5,500.",
          "priority": "HIGH"
        },
        {
          "title": "Activate Email CTA & On-Site Journeys for Low Engagement",
          "action": "Target the 2,667 Low Engagement customers with A/B-tested email CTAs and interactive landing content to boost EmailClicks and TimeOnSite, lifting conversion from 76.45% toward >85%.",
          "priority": "MEDIUM"
        },
        {
          "title": "Accelerate Bronze Users Past 1,000 Loyalty Points",
          "action": "Introduce post-first-purchase milestone bonus points for the 1,583 Bronze customers to bridge the 10.7 pp gap into Silver conversion levels (89.65%).",
          "priority": "MEDIUM"
        },
        {
          "title": "Retire Demographic-Only Targeting & Enrich Telemetry",
          "action": "Shift audience rules from demographics to behavioral intent signals and add CampaignDate, Revenue, and unmasked platform identifiers to enable future time-series and ROAS evaluation.",
          "priority": "STRATEGIC"
        }
      ],
      "conclusion": "Digital marketing conversion is driven primarily by behavioral engagement, conversion-focused campaign intent, and loyalty activation above 1,000 points rather than demographics or channel mix. Capping spend above $7,500 and prioritizing intent signals can cut CPA while sustaining volume."
    },
