    "projectInfo": {
      "projectType": "Full-Stack Job Portal & Recruitment System",
      "developmentStatus": "Completed",
      "developmentYear": "2026",
      "platform": "Web Browser (Desktop & Mobile Responsive)",
      "projectCategory": "Web Development"
    },
    "projectBackground": "Modern hiring workflows frequently suffer from fragmented tools, unverified employer listings, stale applicant profiles, and overlapping interview bookings. HireConnect was engineered as a unified recruitment portal separating Seeker, Employer, and Admin workspaces with auditable server-side workflows.",
    "problemStatements": [
      {
        "title": "Mutable Candidate Profiles Corrupt Historical Applications",
        "description": "When job seekers edit their experience, phone sharing preferences, or delete resumes after applying, recruiters lose the exact credentials that were submitted for evaluation.",
        "issueCode": "ISSUE_01"
      },
      {
        "title": "Race Conditions & Duplicate Submissions Under Concurrency",
        "description": "Simultaneous application requests or concurrent edits to job status and deadlines can allow duplicate applications or submissions to recently closed postings.",
        "issueCode": "ISSUE_02"
      },
      {
        "title": "Unsafe File Uploads & Uncontrolled Document Access",
        "description": "Accepting unvalidated PDF resumes or serving candidate files through static public directories exposes recruiters to active PDF exploits and unauthorized cross-tenant downloads.",
        "issueCode": "ISSUE_03"
      },
      {
        "title": "Scheduling Conflicts & Non-Deterministic Hiring Transitions",
        "description": "Manual interview coordination across timezones leads to double-booked candidates, while ad-hoc status updates create invalid hiring states and orphaned schedules.",
        "issueCode": "ISSUE_04"
      }
    ],
    "projectObjectives": [
      {
        "title": "Enforce Immutable Point-in-Time Application Snapshots",
        "description": "Capture frozen JSON profile snapshots, screening answers, and retained CV references upon submission so hiring records remain intact even if a seeker later updates or deletes their CV.",
        "targetTag": "TARGET_01"
      },
      {
        "title": "Guarantee Transactional & Concurrency-Safe Workflows",
        "description": "Protect application submissions with PostgreSQL row locks and unique composite indexes while defending mutable entities with optimistic concurrency Version tokens.",
        "targetTag": "TARGET_02"
      },
      {
        "title": "Harden Private PDF Storage & Role-Scoped Access",
        "description": "Validate PDF headers, EOF markers, page structure, and forbidden active tags before persisting files outside web roots with authorization-verified streaming downloads.",
        "targetTag": "TARGET_03"
      },
      {
        "title": "Deliver Unified Multi-Role Recruitment Observability",
        "description": "Provide real-time role-scoped dashboards, automated interview conflict detection, transactional email outbox delivery, and immutable administrative audit logs.",
        "targetTag": "TARGET_04"
      }
    ],
    "coreFeatures": [
      {
        "title": "Multi-Criteria Job Discovery & Confidential Salary Filtering",
        "description": "Public paginated job board supporting keyword search, OR filtering within taxonomy groups, AND filtering across categories, and salary overlap queries that exclude confidential listings.",
        "badge": "Job Discovery"
      },
      {
        "title": "Immutable Snapshots & Row-Locked Submissions",
        "description": "Locks target job rows during application transactions to validate active deadlines and company verification before freezing candidate profile data and screening answers.",
        "badge": "Candidate Pipeline"
      },
      {
        "title": "Private PDF Vault with Active-Content Sanitization",
        "description": "Inspects CV and legal document uploads for valid PDF signatures, PdfPig parseability, and absence of JavaScript, Launch, or EmbeddedFile triggers prior to private storage.",
        "badge": "Document Security"
      },
      {
        "title": "Timezone-Aware Interview & Conflict Engine",
        "description": "Schedules multi-round interviews with explicit IANA timezone conversion to UTC, prevents overlapping candidate sessions, supports reschedule requests, and auto-cancels on terminal outcomes.",
        "badge": "Scheduling"
      },
      {
        "title": "Employer Verification & Email-Bound Team Invites",
        "description": "Requires admin approval of uploaded legal documents before publishing jobs, auto-pauses listings if legal metadata changes, and supports 3-day single-use team invitations.",
        "badge": "Tenant Governance"
      },
      {
        "title": "Admin Moderation, Formula-Safe CSV Export & Audit Log",
        "description": "Equips administrators with user controls, company verification, optional job pre-moderation, report resolution, reference management, and full JSON-diff audit trails.",
        "badge": "Administration"
      }
    ],
