    "telemetryMatrix": {
      "projectType": "Full-Stack Hospitality Platform",
      "targetPlatform": "Web Browser & Docker Containers",
      "primaryDomain": "Hotel Reservation & Operations",
      "architecturePipeline": "Angular -> Nginx -> ASP.NET Core -> MySQL",
      "testingAndAudit": "Passed",
      "projectStatus": "Completed",
      "projectYear": "2026"
    },
    "projectInfo": {
      "projectType": "Full-Stack Web Application",
      "developmentStatus": "Completed",
      "developmentYear": "2026",
      "platform": "Web Browser & Containerized Services",
      "projectCategory": "Web Development"
    },
    "projectBackground": "Hospitality operations frequently suffer from fragmented tools where public booking engines lack real-time unit readiness, concurrent checkouts oversell limited rooms, and refund tracking diverges from payment records. HotelEase resolves these gaps in one cohesive multi-property system.",
    "problemStatements": [
      {
        "title": "Concurrent Room Overselling Under Checkout Contention",
        "description": "Without serialized database locking across stay dates, simultaneous guest bookings or staff unit blocks can allocate the same physical room inventory twice.",
        "issueCode": "ISSUE_01"
      },
      {
        "title": "Disconnected Housekeeping & Front-Desk Readiness",
        "description": "When physical room inspection states are tracked outside the reservation system, front-desk staff risk assigning uncleaned or uninspected rooms at check-in.",
        "issueCode": "ISSUE_02"
      },
      {
        "title": "Duplicate Payment Callbacks & Late-Settlement Conflicts",
        "description": "Payment gateway retries or delayed webhook settlements arriving after a hold expires can corrupt booking confirmation states or lose refund accountability.",
        "issueCode": "ISSUE_03"
      },
      {
        "title": "Cross-Tenant Staff Access & Price Drift Risks",
        "description": "Multi-hotel platforms require strict property-scoped role enforcement and immutable booking price snapshots so subsequent rate edits never alter confirmed folios.",
        "issueCode": "ISSUE_04"
      }
    ],
    "projectObjectives": [
      {
        "title": "Zero Overselling via Hotel-Level InnoDB Locking",
        "description": "Serialize all availability-mutating actions with READ COMMITTED transactions and SELECT FOR UPDATE hotel locks across nightly intervals.",
        "targetTag": "TARGET_01"
      },
      {
        "title": "Enforced Sequential Room Readiness Pipeline",
        "description": "Separate sellable room types from physical room units and require sequential To Clean, Cleaned, and Inspected transitions before check-in.",
        "targetTag": "TARGET_02"
      },
      {
        "title": "Idempotent Settlement & Decoupled Refund Ledger",
        "description": "Deduplicate gateway callbacks using unique PaymentEvents keys and record late settlements as separate Refund entries without reviving expired holds.",
        "targetTag": "TARGET_03"
      },
      {
        "title": "Verifiable Multi-Role Governance & Audit Trail",
        "description": "Enforce server-side RBAC across Customer, Manager, FrontDesk, Housekeeping, and Admin roles with immutable JSON audit logging.",
        "targetTag": "TARGET_04"
      }
    ],
    "coreFeatures": [
      {
        "title": "Nightly Availability & Multi-Room Checkout",
        "description": "Calculates peak nightly occupancy across [checkIn, checkOut) dates, supports multi-room-type selections with per-room guest names, and holds inventory during payment.",
        "badge": "Booking Engine"
      },
      {
        "title": "Dynamic Rate Calendar & Rate Plans",
        "description": "Applies date-specific RateCalendar overrides, weekend tariffs, and percentage-adjusted refundable or non-refundable rate plans with JSON price snapshots.",
        "badge": "Revenue & Pricing"
      },
      {
        "title": "Front-Desk Check-In, Check-Out & Walk-In Ops",
        "description": "Validates payment status, local check-in window, and physical unit readiness during check-in, and generates housekeeping tasks automatically upon check-out.",
        "badge": "Front Office"
      },
      {
        "title": "Housekeeping Sequential Task Board",
        "description": "Tracks room cleaning stages sequentially from To Clean through Cleaned to Inspected with staff assignments and room notes.",
        "badge": "Housekeeping"
      },
      {
        "title": "Midtrans Snap & LocalSandbox Payment Flows",
        "description": "Supports SHA-512 verified Midtrans webhooks, manual staff payments, gateway status reconciliation, downloadable text receipts, and decoupled refunds.",
        "badge": "Payments"
      },
      {
        "title": "Financial & Occupancy Reporting with CSV Export",
        "description": "Computes collected funds, processed refunds, net revenue, daily payment breakdowns, and period occupancy rates using RoomInventoryHistory denominators.",
        "badge": "Analytics"
      },
      {
        "title": "Platform Moderation & Audit Explorer",
        "description": "Provides administrators with hotel publication approval workflows, user/staff suspension with instant session revocation, global hold settings, and audit logs.",
        "badge": "Governance"
      }
    ],
