    "systemArchitecture": {
      "summary": "The platform separates a Next.js App Router frontend from a stateless Go HTTP API and PostgreSQL database. Next.js proxies all /api requests to the Go backend while serving public SSR portfolio pages, enforcing strict origin checks, optimistic revision locks, and server-side image re-encoding.",
      "layers": [
        {
          "name": "Presentation & Proxy Layer",
          "role": "Renders the dashboard workspace, SSR public portfolios (/p/[slug]), and proxies /api/* calls with security headers.",
          "components": [
            "Next.js App Router",
            "React Feature Modules",
            "API Route Proxy"
          ]
        },
        {
          "name": "API & Security Middleware Layer",
          "role": "Handles routing, CSRF origin validation, Content-Type enforcement, IP/email rate limiting, and RBAC session guards.",
          "components": [
            "Go net/http ServeMux",
            "Session Cookie Auth",
            "In-Memory Rate Limiter"
          ]
        },
        {
          "name": "Domain & Media Processing Layer",
          "role": "Enforces schema bounds, privacy snapshot filtering (domain.Public), bcrypt hashing, and Catmull-Rom JPEG re-encoding.",
          "components": [
            "Domain Validator",
            "CatmullRom Image Scaler",
            "SMTP Token Mailer"
          ]
        },
        {
          "name": "Persistence & Storage Layer",
          "role": "Stores relational users, JSONB drafts/snapshots, slug locks, events, audit logs, and JPEG binaries on persistent volumes.",
          "components": [
            "PostgreSQL 17 pgxpool",
            "Embedded SQL Migrations",
            "Local Upload Volume"
          ]
        }
      ]
    },
