        {
          "title": "Pre-Stage Cross-Trained Surge Capacity for Q3-Q4",
          "action": "Allocate seasonal cross-trained compliance staffing ahead of July-October (+25%-30% historical volume surge over Q1) to prevent recurring autumn SLA compression.",
          "priority": "STRATEGIC"
        }
