    "dataAnalyticsKeyFindings": [
      {
        "metricValue": "0.04",
        "metricLabel": "Budget-Purchase Rho",
        "title": "Budget Allocation Disconnected from Conversions",
        "description": "Campaign total_budget exhibits no significant monotonic correlation with purchases (Spearman rho = 0.0413, p = 0.78) while strongly inflating CPA (rho = 0.6699, p < 0.0001), because delivery scales with ad_count (r = 0.9350).",
        "impactTag": "Budget Efficiency"
      },
      {
        "metricValue": "6.03%",
        "metricLabel": "Idle Budget Share",
        "title": "Capital Frozen in Zero-Delivery Campaigns",
        "description": "Two campaigns (Campaign_16_Winter and Campaign_43_Winter) hold 152,872.18 budget units out of 2,535,923.78 total spend with zero active ads and zero recorded events.",
        "impactTag": "Capital Waste"
      },
      {
        "metricValue": "55.1x",
        "metricLabel": "Campaign CPA Spread",
        "title": "Extreme Acquisition Cost Variance Across Campaigns",
        "description": "Active campaign CPA ranges from 118.18 on Campaign_42_Summer (8 ads, 67 purchases) to 6,511.53 on Campaign_35_Launch (1 ad, 11 purchases).",
        "impactTag": "Cost Optimization"
      },
      {
        "metricValue": "93.85%",
        "metricLabel": "Off-Target Events",
        "title": "Massive Multi-Attribute Targeting Leakage",
        "description": "Only 6.15% of events (24,608) match gender, age group, and interests simultaneously, driven by 22.21% interest alignment and 44.99% age alignment, with no significant CVR lift (p = 0.69).",
        "impactTag": "Targeting Audit"
      },
      {
        "metricValue": "5.34%",
        "metricLabel": "Stories Format CVR",
        "title": "Stories Leads Conversion Volume Across Platforms",
        "description": "Stories generates the highest purchase volume (683) and CVR (5.34%, peaking at 5.52% on Facebook Stories), whereas Instagram Image posts the highest CTR (12.17%) but lowest CVR (4.35%).",
        "impactTag": "Creative Performance"
      },
      {
        "metricValue": "6.39%",
        "metricLabel": "Japan Peak CVR",
        "title": "Statistically Significant Geographic Conversion Differences",
        "description": "Country-level purchase independence is significant (chi2 = 22.49, p = 0.0074), with Japan (6.39%) and Mexico (6.13%) outperforming France (4.14%) while the United States anchors 32.20% of volume (654 purchases).",
        "impactTag": "Market Strategy"
      }
    ],
    "recommendationsAndConclusion": {
      "recommendations": [
        {
          "title": "Reallocate Idle Budget & Cap Extreme-CPA Campaigns",
          "action": "Unfreeze and redistribute the 152,872.18 idle spend from Campaign_16_Winter and Campaign_43_Winter while capping or restructuring campaigns exceeding 5,800 CPA.",
          "priority": "HIGH"
        },
        {
          "title": "Enforce Minimum Creative-to-Budget Ratios",
          "action": "Require at least 5 to 8 active ad variants for mid-to-high-budget campaigns and activate budget-paced delivery to eliminate single-ad bottlenecks.",
          "priority": "HIGH"
        },
        {
          "title": "Tighten Audience Targeting & Exclusion Rules",
          "action": "Audit audience expansion settings to raise interest match (22.21%) and full-match delivery above 6.15%, validating conversion lift through controlled A/B tests.",
          "priority": "MEDIUM"
        },
        {
          "title": "Scale Stories & High-Converting Geographic Markets",
          "action": "Run measured scaling tests in Japan (6.39% CVR), Mexico (6.13% CVR), and the US using Facebook Stories while auditing post-click landing pages for Instagram Image.",
          "priority": "MEDIUM"
        },
        {
          "title": "Instrument Revenue Tracking & Campaign Date Validation",
          "action": "Capture transaction order values, daily spend logs, and strict campaign date enforcement (55.63% of events currently fall outside scheduled dates) to enable ROAS analysis.",
          "priority": "STRATEGIC"
        }
      ],
      "conclusion": "Portfolio optimization hinges on shifting governance from raw budget size to verified creative density, targeting precision, and regional conversion intent. Implementing minimum ad-to-budget ratios, reclaiming 6.03% idle spend, and instrumenting revenue tracking will convert descriptive visibility into measurable ROAS."
    },
