    "license": "MIT License",
    "banner": "/images/projects/foodorder_online_food_ordering/banner.webp",
    "summary": "Full-stack food ordering and multi-role restaurant platform with idempotent checkout, HMAC webhooks, and resilient outbox workers.",
    "projectDescription": "FoodOrder unifies customer food discovery, server-authoritative checkout, restaurant kitchen fulfillment, and platform governance. Built with Spring Boot, React, PostgreSQL, and Redis, it enforces idempotent orders, row-locked promo quotas, signed webhooks, and resilient outbox jobs.",
    "architectureSummary": "Nginx same-origin proxy fronts a React SPA and Spring Boot API backed by PostgreSQL transactional outbox storage, Redis caching, and a dedicated Worker.",
    "techStack": [
      "Java",
      "Spring Boot",
      "React",
      "TypeScript",
      "Vite",
      "Bootstrap",
      "Recharts",
      "PostgreSQL",
      "Redis",
      "Flyway",
      "Nginx",
      "Docker"
    ],
    "telemetryMatrix": {
      "projectType": "Full-Stack Commerce & Ops Platform",
      "targetPlatform": "Web Browser & Containerized Stack",
      "primaryDomain": "Food Delivery & Restaurant Management",
      "architecturePipeline": "SPA -> Nginx -> Spring API -> DB/Redis/Worker",
      "testingAndAudit": "Passed",
      "projectStatus": "Completed",
      "projectYear": "2026"
    },
    "projectInfo": {
      "projectType": "Full-Stack Web Application",
      "developmentStatus": "Completed",
      "developmentYear": "2026",
      "platform": "Web (Docker Compose + Nginx + JVM)",
      "projectCategory": "Web Development"
    },
    "projectBackground": "Online food ordering platforms often suffer from race conditions when concurrent diners claim limited vouchers, cart prices drift before checkout, or payment callbacks arrive multiple times. FoodOrder addresses these operational failures with strict server-side pricing, explicit role boundaries, and durable background processing.",
    "problemStatements": [
      {
        "title": "Concurrent Promotion Quota Overbooking",
        "description": "High-demand discount codes can exceed their configured total quota or per-customer usage limits if multiple checkouts validate availability concurrently without transactional row locks.",
        "issueCode": "ISSUE_01"
      },
      {
        "title": "Price Drift & Duplicate Order Submissions",
        "description": "Client-side price trust or network retries during checkout can cause customers to pay outdated menu totals or accidentally place duplicate orders from a single cart session.",
        "issueCode": "ISSUE_02"
      },
      {
        "title": "Unreliable Asynchronous Notifications & Refunds",
        "description": "Executing notifications, payment timeouts, and refund settlements inline inside HTTP requests slows responses and risks losing side effects if a cache or queue broker restarts.",
        "issueCode": "ISSUE_03"
      },
      {
        "title": "Leaked Unpaid Orders & Weak Role Isolation",
        "description": "Kitchen dashboards that display unpaid checkouts or fail to enforce restaurant ownership allow unauthorized staff actions and premature food preparation.",
        "issueCode": "ISSUE_04"
      }
    ],
    "projectObjectives": [
      {
        "title": "Enforce Server-Authoritative Idempotent Checkout",
        "description": "Compute all Rupiah amounts in integer bigint from PostgreSQL row locks, validate quote fingerprints against frontend approval, and deduplicate orders via (customer_id, idempotency_key).",
        "targetTag": "TARGET_01"
      },
      {
        "title": "Decouple Payment Verification from Fulfillment",
        "description": "Verify raw JSON webhook payloads with constant-time HMAC-SHA256 signatures, enforce unique event_id deduplication, and expose orders to kitchens only after PAID confirmation.",
        "targetTag": "TARGET_02"
      },
      {
        "title": "Guarantee Durable Outbox & Redis Fallback",
        "description": "Persist notifications and refunds in PostgreSQL background_jobs within the triggering transaction, dispatch via Redis lists, and fall back to PostgreSQL polling during Redis outages.",
        "targetTag": "TARGET_03"
      },
      {
        "title": "Isolate Multi-Role Operations & Auditability",
        "description": "Enforce backend RBAC across Customer, Staff, Manager, and Admin roles with HttpOnly SHA-256 session cookies and immutable before/after audit logging.",
        "targetTag": "TARGET_04"
      }
    ],
    "coreFeatures": [
      {
        "title": "Haversine Discovery & Catalog Caching",
        "description": "Filter active restaurants by keyword, category, rating, price level, and Haversine coordinate radius, backed by 60-second Redis caching with post-commit invalidation.",
        "badge": "DISCOVERY"
      },
      {
        "title": "Variant-Aware Cart & Quote Fingerprint Checkout",
        "description": "Manage single-restaurant carts with required variants, add-ons, and notes, then verify delivery distance, row-locked promo quotas, and quote fingerprints before order commit.",
        "badge": "COMMERCE"
      },
      {
        "title": "Fulfillment State Machine & Automated Refunds",
        "description": "Advance paid orders from PENDING_RESTAURANT through COMPLETED with strict actor rules, automatic timeout rejections, customer cancellations, and full or partial refunds.",
        "badge": "FULFILLMENT"
      },
      {
        "title": "Restaurant Analytics, Menu CRUD & CSV Export",
        "description": "Equip restaurant managers and staff with live order queues, menu/category/staff management, Recharts sales visualizations, and daily aggregated CSV financial exports.",
        "badge": "OPERATIONS"
      },
      {
        "title": "Platform Governance, Audit Logs & Worker Health",
        "description": "Provide administrators with restaurant onboarding, user suspension, promo rules, cross-restaurant transaction monitoring, dead-letter job retries, and fee settings.",
        "badge": "ADMIN"
      }
    ],
