    "technicalImplementation": [
      {
        "category": "Concurrency & Idempotency",
        "title": "Row-Locked Checkout, Promo Quotas & Snapshot Fingerprints",
        "description": "Checkout locks the user's cart row, reads authoritative prices directly from PostgreSQL bypassing Redis cache, locks promo rows with FOR UPDATE, verifies the frontend quote fingerprint, and enforces UNIQUE(customer_id, idempotency_key).",
        "badge": "ACID LOCKS"
      },
      {
        "category": "Payment Security",
        "title": "Constant-Time HMAC-SHA256 Raw Body Webhook Verification",
        "description": "Incoming payment callbacks validate X-Payment-Signature over raw UTF-8 JSON bytes using PAYMENT_WEBHOOK_SECRET, enforce unique event_id deduplication, lock order/payment rows, and prevent illegal final state transitions.",
        "badge": "HMAC GUARD"
      },
      {
        "category": "Resilient Messaging",
        "title": "Transactional Outbox with Redis Queue & PostgreSQL Fallback",
        "description": "Notification and refund jobs commit atomically inside background_jobs, dispatch to Redis lists with 30-second dedupe keys, lock via FOR UPDATE SKIP LOCKED, retry up to 5 times with exponential backoff, and fall back to DB polling if Redis fails.",
        "badge": "OUTBOX WORKER"
      },
      {
        "category": "Auth & CSRF Defense",
        "title": "SHA-256 Session Cookies & Origin Validation Filter",
        "description": "Sessions store SHA-256 digests in PostgreSQL with HttpOnly/SameSite=Lax cookies and BCrypt cost 10 password hashes, while RequestGuard blocks cross-site mutations and rate-limits auth endpoints at 40 requests per minute.",
        "badge": "RBAC & CSRF"
      }
    ],
