    "dataAnalyticsKeyFindings": [
      {
        "metricValue": "10.53%",
        "metricLabel": "Overall Conversion Rate",
        "title": "2018 Structural Funnel Inflection",
        "description": "842 of 8,000 MQLs closed overall, with cohort conversion surging from 3.05% in H2 2017 to 13.02% in Jan-May 2018 (Spearman rho=0.8951, p=0.0001).",
        "impactTag": "Funnel Growth"
      },
      {
        "metricValue": "12.30%",
        "metricLabel": "Paid Search Conversion",
        "title": "Search Channels Outperform Social >2x and Email 4x",
        "description": "Paid Search (12.30%) and Organic Search (11.80%) convert significantly higher than Social (5.56%, 30.56d cycle) and Email (3.04%) with Chi-Square p=3.05e-25.",
        "impactTag": "Channel Efficiency"
      },
      {
        "metricValue": "22.92%",
        "metricLabel": "Unattributed Deal Share",
        "title": "Severe Attribution Blind Spot on High-Intent Leads",
        "description": "Unknown (16.29% CR) and Missing (23.33% CR) origins make up 14.49% of MQLs yet generate 193 of 842 closed deals due to broken UTM tracking.",
        "impactTag": "Attribution"
      },
      {
        "metricValue": "69.12%",
        "metricLabel": "Top-10 LP Deal Share",
        "title": "Extreme Landing Page Pareto & High-Traffic Leakage",
        "description": "361 of 495 pages produced zero deals while Top 10 drove 69.12% of wins; high-traffic LP-003 (5.45%) and LP-008 (3.44%) trail top pages (~19-20%).",
        "impactTag": "CRO Opportunity"
      },
      {
        "metricValue": "14.7d",
        "metricLabel": "Median Sales Cycle",
        "title": "Fast Sub-14-Day Closing Skewed by Long-Tail Deals",
        "description": "48.81% of deals close within 14 days, whereas 17.93% take over 90 days (up to 427.6 days), inflating the mean to 49.16 days.",
        "impactTag": "Sales Velocity"
      },
      {
        "metricValue": "49.89%",
        "metricLabel": "Top-5 SDR Deal Share",
        "title": "High Key-Person Dependency Across SDRs & SRs",
        "description": "Top 5 of 32 SDRs handle 49.89% of closed deals and Top 5 of 22 SRs close 49.41%, creating bottleneck and attrition risk.",
        "impactTag": "Team Capacity"
      }
    ],
    "recommendationsAndConclusion": {
      "recommendations": [
        {
          "title": "Enforce UTM & Referrer Persistence Across Landing Pages",
          "action": "Audit all 495 landing pages (prioritizing Top 20 pages carrying 63.88% of MQLs) with hidden form fields and server-side UTM capture to cut unattributed MQLs below 5%.",
          "priority": "HIGH"
        },
        {
          "title": "Redesign & A/B Test Lagging High-Traffic Pages LP-003 and LP-008",
          "action": "Replicate value proposition and form design from LP-001 (18.75%), LP-002 (19.71%), and LP-006 (20.30%) on LP-003 and LP-008 while retiring zero-deal pages.",
          "priority": "HIGH"
        },
        {
          "title": "Tighten Social & Email Qualification and Test Search Reallocation",
          "action": "Refine Social (5.56% CR) and Email (3.04% CR) targeting with pre-qualification filters and shift incremental budget toward Paid Search and SEO once CAC tracking is active.",
          "priority": "MEDIUM"
        },
        {
          "title": "Balance SDR/SR Lead Routing & Enforce 14-Day SLA",
          "action": "Redistribute pipeline beyond the Top 5 SDRs/SRs, apply a 48-hour first-touch SLA with 30-day aging reviews, and standardize fast-close playbooks from top pairs.",
          "priority": "MEDIUM"
        },
        {
          "title": "Mandate CRM Validation & Post-Onboarding GMV Linking",
          "action": "Block negative-date entries (won_date >= first_contact_date), capture core seller enrichment attributes (>91% missing), and integrate realized seller GMV for LTV/ROAS tracking.",
          "priority": "STRATEGIC"
        }
      ],
      "conclusion": "Olist's 10.53% funnel conversion rate reflects strong Search intent and rapid sub-14-day closing alongside severe channel polarization, 14.49% unattributed MQLs, and high landing page and rep concentration. Fixing UTM tracking, optimizing LP-003 and LP-008, and balancing SDR/SR routing unlock immediate growth."
    },
