    "id": "clouddrive-personal-cloud-storage-platform",
    "code": "PRO-94 // WEB-25",
    "title": "CloudDrive - Personal Cloud Storage Platform",
    "category": "web-development",
    "categoryLabel": "Website",
    "year": "2026",
    "status": "Completed",
    "accentColor": "cyan",
    "repoUrl": "https://github.com/weztcy/CloudDrive-Personal-Cloud-Storage-Platform",
    "license": "MIT License",
    "banner": "/images/projects/clouddrive_personal_cloud_storage/banner.webp",
    "summary": "Full-stack personal cloud storage platform built with Rust, Axum, PostgreSQL, and Svelte for private file management and controlled sharing.",
    "projectDescription": "CloudDrive is a full-stack personal cloud storage platform powered by a Rust Axum API, PostgreSQL, and Svelte. It delivers streaming uploads with magic-byte validation, hierarchical folders, ZIP archiving, 30-day recycle bin retention, HMAC-protected sharing, and an admin console.",
    "architectureSummary": "Svelte 5 SPA served by Nginx reverse-proxying unbuffered streaming API requests to a Rust Axum backend backed by PostgreSQL 17 and local object storage.",
    "techStack": [
      "Rust",
      "Axum",
      "Tokio",
      "SQLx",
      "PostgreSQL",
      "Svelte",
      "TypeScript",
      "Tailwind CSS",
      "Vite",
      "Nginx",
      "Docker",
      "Playwright"
    ],
    "telemetryMatrix": {
      "projectType": "Full-Stack Cloud Storage Web App",
      "targetPlatform": "Web Browser via Docker and Nginx",
      "primaryDomain": "Personal Cloud Storage and File Sharing",
      "architecturePipeline": "Svelte -> Nginx -> Axum API -> PostgreSQL",
      "testingAndAudit": "Passed",
      "projectStatus": "Completed",
      "projectYear": "2026"
    },
    "projectInfo": {
      "projectType": "Full-Stack Personal Cloud Storage Platform",
      "developmentStatus": "Completed",
      "developmentYear": "2026",
      "platform": "Web (Desktop & Mobile Responsive)",
      "projectCategory": "Web Development"
    },
    "projectBackground": "Self-hosted personal cloud storage requires strict data integrity, zero quota drift, and safe public sharing without relying on third-party object gateways. CloudDrive was engineered to unify low-overhead Rust binary streaming, transactional PostgreSQL locks, and a responsive Svelte workspace in a single deployable stack.",
    "problemStatements": [
      {
        "title": "Concurrent Upload Quota Race Conditions",
        "description": "Simultaneous file uploads from multiple tabs can exceed a user's storage allocation if quota checks and byte counters are evaluated outside serialized database transactions.",
        "issueCode": "ISSUE_01"
      },
      {
        "title": "Spoofed File Extensions & Path Traversal",
        "description": "Relying solely on client-supplied MIME headers or filenames allows malformed payloads, executable uploads, or directory traversal sequences to enter object storage.",
        "issueCode": "ISSUE_02"
      },
      {
        "title": "Partial Subtree Restores & Orphaned Blobs",
        "description": "Naive soft deletes can accidentally restore previously trashed child files alongside a parent folder or leave unreferenced binary objects stranded on disk after metadata purges.",
        "issueCode": "ISSUE_03"
      },
      {
        "title": "Exposure of Internal IDs in Public Share URLs",
        "description": "Sharing files via sequential or raw database UUIDs exposes internal identifiers and prevents administrators from managing link validity without storing raw secrets.",
        "issueCode": "ISSUE_04"
      }
    ],
    "projectObjectives": [
      {
        "title": "Transactional Quota & Atomic Commit Guarantees",
        "description": "Acquire PostgreSQL row locks per user during file mutations and recalculate usage dynamically via SUM(size) before committing staged uploads.",
        "targetTag": "TARGET_01"
      },
      {
        "title": "Strict Magic-Byte & OOXML Signature Verification",
        "description": "Normalize filenames with Unicode NFC, strip unsafe path characters, and inspect binary headers and ZIP/Office internal XML manifests before storage commit.",
        "targetTag": "TARGET_02"
      },
      {
        "title": "Batch-Isolated Recycle Bin & Automated GC",
        "description": "Tag subtree deletions with a deletion_batch UUID for accurate restores, queue purged keys in storage_gc, and run hourly retention and orphan reconciliation.",
        "targetTag": "TARGET_03"
      },
      {
        "title": "Privacy-Preserving Sharing & Admin Governance",
        "description": "Sign public share tokens via HMAC-SHA256, hash all session and share tokens in PostgreSQL, and restrict admin visibility strictly to operational metadata.",
        "targetTag": "TARGET_04"
      }
    ],
    "coreFeatures": [
      {
        "title": "Streaming Uploads & Signature Validation",
        "description": "Streams raw binary bodies into guarded temporary files, enforces per-plan and global size caps, validates magic bytes and OOXML manifests, and commits atomically.",
        "badge": "Storage Engine"
      },
      {
        "title": "Hierarchical Explorer & Multi-File ZIP",
        "description": "Supports nested folders with recursive breadcrumbs, cycle detection, list/grid views, starred bookmarks, file duplication, and on-the-fly multi-file ZIP streaming.",
        "badge": "File Management"
      },
      {
        "title": "Global Search, Filters & Pagination",
        "description": "Queries active items across all folders with escaped ILIKE matching, category tabs (Documents, Images, Archives), multi-column sorting, and paginated responses.",
        "badge": "Discovery"
      },
      {
        "title": "Batch-Tracked Recycle Bin & Retention",
        "description": "Preserves original locations on soft delete, prevents name collisions during restore, enforces 1–365 day configurable retention, and reclaims storage on permanent purge.",
        "badge": "Lifecycle"
      },
      {
        "title": "HMAC-Signed Public Share Links",
        "description": "Creates permission-scoped (view or download) share links with optional Argon2 passwords, expiration dates up to 365 days, instant revocation, and public access logging.",
        "badge": "Sharing"
      },
      {
        "title": "Admin Console & Storage Reconciliation",
        "description": "Provides user account search, plan assignment, custom plan CRUD, audit trail inspection, retention settings, and manual orphan/missing-object reconciliation.",
        "badge": "Administration"
      }
    ],
