    "userFlow": {
      "summary": "Users authenticate into an isolated 24-hour workspace, navigate hierarchical folders or global search, stream-upload validated files under real-time quota checks, preview or share items via permissioned public URLs, and manage deleted subtrees or account security.",
      "steps": [
        {
          "step": "01",
          "title": "Authenticate or Explore Demo",
          "description": "User registers, signs in via Argon2-verified credentials, or triggers the demo workspace to receive an opaque 24-hour Bearer session token.",
          "actorOrNode": "AuthScreen / POST /api/auth/login"
        },
        {
          "step": "02",
          "title": "Inspect Quota & Recent Workspace",
          "description": "Dashboard fetches live SUM(size) storage telemetry, category breakdowns, Quick Access cards, and recent activity logs.",
          "actorOrNode": "App.svelte / GET /api/summary"
        },
        {
          "step": "03",
          "title": "Browse Folders & Stream Upload",
          "description": "User creates nested folders or streams binary files; backend verifies extension, magic bytes, and row-locked quota before committing to disk.",
          "actorOrNode": "POST /api/items/upload"
        },
        {
          "step": "04",
          "title": "Preview, Archive & Organize",
          "description": "User previews images/PDFs via authorized blob fetches, toggles starred favorites, copies files, or downloads multiple selections as a ZIP archive.",
          "actorOrNode": "GET /api/items/{id}/content"
        },
        {
          "step": "05",
          "title": "Create Controlled Share Links",
          "description": "User issues an HMAC-SHA256 share URL with view/download permission, expiry, and optional password; recipients access content via POST /api/public/{token}.",
          "actorOrNode": "PublicShare / POST /api/shares"
        },
        {
          "step": "06",
          "title": "Recycle Bin & Admin Governance",
          "description": "Soft-deleted subtrees are restored or purged cleanly, while administrators manage user plans, retention policies, audits, and storage reconciliation.",
          "actorOrNode": "Admin.svelte / Maintenance Worker"
        }
      ]
    },
    "systemArchitecture": {
      "summary": "CloudDrive uses a four-service Docker Compose topology where Nginx delivers the compiled Svelte 5 SPA with strict security headers and reverse-proxies unbuffered /api/ streams to an Axum Rust API backed by PostgreSQL 17, local object storage, and a Mailpit SMTP relay.",
      "layers": [
        {
          "name": "Client & Edge Proxy Layer",
          "role": "Delivers compiled static assets with strict CSP/nosniff headers and unbuffered streaming proxy routes for large binary transfers.",
          "components": [
            "Svelte 5 SPA",
            "Nginx Reverse Proxy",
            "Content Security Policy",
            "Vite Asset Bundle"
          ]
        },
        {
          "name": "API & Security Middleware Layer",
          "role": "Handles 37 REST endpoints, opaque SHA-256 Bearer extraction, sliding-window rate limiting, and consistent JSON error normalization.",
          "components": [
            "Axum Router",
            "Tower HTTP TraceLayer",
            "DefaultBodyLimit",
            "Auth & RBAC Extractors"
          ]
        },
        {
          "name": "Storage & Lifecycle Worker Layer",
          "role": "Performs temp-file upload staging, magic-byte/OOXML signature inspection, ZIP archive generation, and hourly retention/orphan garbage collection.",
          "components": [
            "ObjectStorage Trait",
            "LocalStorage Adapter",
            "TempFile & PendingObject Guards",
            "Hourly Maintenance Loop"
          ]
        },
        {
          "name": "Relational Metadata & Email Layer",
          "role": "Stores hierarchical item metadata, share hashes, immutable activity/admin audits, and dispatches single-use password reset emails.",
          "components": [
            "PostgreSQL 17",
            "SQLx Migrations",
            "Lettre SMTP Client",
            "Mailpit Test Relay"
          ]
        }
      ]
    },
    "databaseDataFlow": {
      "type": "Database Schema / ERD",
      "summary": "PostgreSQL enforces folder-name uniqueness via case-insensitive partial indexes, isolates file metadata from binary storage keys, and queues deleted keys in storage_gc for retry-safe physical cleanup.",
      "entitiesOrPipelines": [
        {
          "name": "users & plans",
          "type": "Table",
          "fields": [
            "id (UUID PK)",
            "email (TEXT UNIQUE)",
            "password_hash (Argon2)",
            "role (user | admin)",
            "plan_id (FK -> plans.id)",
            "quota / max_file_size (BIGINT)"
          ]
        },
        {
          "name": "sessions & password_resets",
          "type": "Table",
          "fields": [
            "token_hash (TEXT PK, SHA-256)",
            "user_id (FK -> users.id ON DELETE CASCADE)",
            "expires_at (TIMESTAMPTZ)"
          ]
        },
        {
          "name": "items",
          "type": "Table",
          "fields": [
            "id (UUID PK)",
            "owner_id (FK -> users.id)",
            "parent_id (Self FK -> items.id)",
            "kind (file | folder)",
            "storage_key (TEXT)",
            "deleted_at / deletion_batch"
          ]
        },
        {
          "name": "shares",
          "type": "Table",
          "fields": [
            "id (UUID PK)",
            "file_id (FK -> items.id ON DELETE CASCADE)",
            "token_hash (TEXT UNIQUE)",
            "permission (view | download)",
            "password_hash / expires_at / revoked_at"
          ]
        },
        {
          "name": "activities & admin_audits",
          "type": "Table",
          "fields": [
            "id (UUID PK)",
            "user_id / admin_id (FK -> users.id)",
            "action (TEXT)",
            "metadata (JSONB)",
            "created_at (TIMESTAMPTZ)"
          ]
        },
        {
          "name": "storage_gc & settings",
          "type": "Table",
          "fields": [
            "storage_key (TEXT PK)",
            "key (retention_days)",
            "value (INTEGER 1-365)"
          ]
        }
      ]
    },
    "technicalImplementation": [
      {
        "category": "Concurrency & Quota",
        "title": "Serialized Row-Locked Quota Enforcement",
        "description": "File uploads, copies, and plan changes acquire a PostgreSQL FOR UPDATE row lock on the owning user inside a transaction and compute live storage usage via SUM(size), returning HTTP 507 on concurrent quota exhaustion.",
        "badge": "ACID Locks"
      },
      {
        "category": "Input & Binary Security",
        "title": "Two-Stage Upload Staging & Signature Validation",
        "description": "Uploads stream via BodyDataStream into RAII-guarded TempFile paths, enforce Unicode NFC clean_name path checks, and inspect PDF/PNG/JPEG magic bytes plus ZIP/OOXML XML entries before atomic rename.",
        "badge": "Zero-Trust Upload"
      },
      {
        "category": "Sharing & Cryptography",
        "title": "Stateless HMAC Share Reconstruction & Hashed Storage",
        "description": "Public share tokens are derived using HMAC-SHA256 over the share UUID and SHARE_TOKEN_SECRET while only SHA-256 digests are stored in PostgreSQL, enabling safe URL copy reconstruction without persisting plaintext tokens.",
        "badge": "HMAC-SHA256"
      },
      {
        "category": "Storage Reliability",
        "title": "Batch Subtree Restore & Orphan GC Reconciliation",
        "description": "Soft deletes tag active subtrees with a shared deletion_batch UUID so restores never revive older trashed children, while purges enqueue keys in storage_gc and hourly workers sweep 24-hour orphan files.",
        "badge": "Garbage Collection"
      }
    ],
    "primaryTechSpecs": {
      "programmingLanguage": "Rust & TypeScript",
      "framework": "Axum & Svelte",
      "database": "PostgreSQL"
    },
    "architectureQuality": {
      "badges": [
        "Transactional Quota Locks",
        "Magic Byte Validation",
        "HMAC Share Tokens",
        "Orphan Garbage Collection"
      ]
    }
