    "userFlow": {
      "summary": "From public doctor discovery through consultation settlement, ClinicCare orchestrates every visit across role-guarded steps: booking a slot, administrative check-in, doctor queue progression, clinical charting and finalization, and cashier payment collection.",
      "steps": [
        {
          "step": "01",
          "title": "Doctor Discovery & Slot Booking",
          "description": "A patient or admin selects a specialization, doctor, and available slot; AppointmentService validates lead time and capacity under advisory locks and issues a BK-XXXXXXXX reservation.",
          "actorOrNode": "Patient / Admin -> AppointmentService"
        },
        {
          "step": "02",
          "title": "Check-In & Queue Number Issuance",
          "description": "Within the clinic check-in window on the visit date, an admin checks the patient in, generating a sequential per-doctor daily queue number in WAITING status.",
          "actorOrNode": "Admin -> QueueController"
        },
        {
          "step": "03",
          "title": "Queue Calling & Clinical Examination",
          "description": "Staff or the assigned doctor calls the queue number; the doctor starts IN_SERVICE examination, records draft or finalized vitals, clinical notes, prescriptions, and attachments.",
          "actorOrNode": "Doctor -> MedicalController"
        },
        {
          "step": "04",
          "title": "Finalization & Auto-Invoicing",
          "description": "Finalizing the medical record locks the chart, marks the appointment and queue COMPLETED, and generates an UNPAID invoice containing a point-in-time service price snapshot.",
          "actorOrNode": "MedicalController -> Billing & Notifications"
        },
        {
          "step": "05",
          "title": "Payment Settlement & Executive Reporting",
          "description": "Cashiers record idempotent partial or full payments via Cash, Transfer, or QRIS, while Management and SYSADMIN review cash-basis revenue and audit trails.",
          "actorOrNode": "Cashier / Management -> BillingController & ReportingController"
        }
      ]
    },
    "systemArchitecture": {
      "summary": "ClinicCare follows a containerized three-tier architecture: Nginx serves the Angular 21 SPA with strict Content-Security-Policy headers and reverse-proxies /api requests to a Spring Boot 3.5.7 REST API backed by PostgreSQL 17, Flyway migrations, and advisory locks.",
      "layers": [
        {
          "name": "Presentation & Edge Gateway",
          "role": "Delivers the Angular 21 single-page application, enforces Content-Security-Policy headers, handles SPA fallback routing, and proxies /api/** to the backend.",
          "components": [
            "Nginx",
            "Angular Router & Role Guards",
            "Bootstrap UI Components"
          ]
        },
        {
          "name": "Security & Access Interceptor",
          "role": "Validates SHA-256 hashed opaque bearer tokens against active database sessions, applies no-store headers, and enforces role, patient-ownership, and clinical-relationship checks.",
          "components": [
            "AuthInterceptor",
            "Access RBAC & Clinical Guard",
            "Audit Logger"
          ]
        },
        {
          "name": "Domain & Scheduling Services",
          "role": "Executes transactional booking, queue transitions, clinical charting, idempotent billing, and periodic 24-hour patient reminders.",
          "components": [
            "AppointmentService",
            "QueueController",
            "MedicalController",
            "BillingController",
            "ReminderJob"
          ]
        },
        {
          "name": "Persistence & Concurrency Layer",
          "role": "Stores relational and JSONB records in PostgreSQL 17 with Flyway migrations, advisory transaction locks, and row-level FOR UPDATE locks.",
          "components": [
            "PostgreSQL",
            "Flyway Migrations",
            "Spring JDBC & Db Normalizer"
          ]
        }
      ]
    },
    "databaseDataFlow": {
      "type": "Database Schema / ERD",
      "summary": "PostgreSQL 17 manages 21 normalized tables and JSONB clinical/settings payloads across identity, scheduling, queue operations, EMR revisions, billing ledger, and audit logging.",
      "entitiesOrPipelines": [
        {
          "name": "users & sessions",
          "type": "Table",
          "fields": [
            "id",
            "email",
            "password_hash",
            "role",
            "active",
            "token_hash",
            "expires_at"
          ]
        },
        {
          "name": "patients & doctors",
          "type": "Table",
          "fields": [
            "patient_number",
            "birth_date",
            "gender",
            "notification_enabled",
            "specialization_id",
            "room"
          ]
        },
        {
          "name": "schedules & appointments",
          "type": "Table",
          "fields": [
            "doctor_id",
            "date",
            "start_time",
            "end_time",
            "slot_minutes",
            "capacity",
            "booking_number",
            "slot",
            "status"
          ]
        },
        {
          "name": "queues",
          "type": "Table",
          "fields": [
            "appointment_id",
            "doctor_id",
            "date",
            "number",
            "status",
            "checked_in_at"
          ]
        },
        {
          "name": "medical_records, record_revisions & addenda",
          "type": "Table",
          "fields": [
            "appointment_id",
            "status",
            "data (JSONB)",
            "finalized_at",
            "content",
            "actor_id"
          ]
        },
        {
          "name": "prescriptions & attachments",
          "type": "Table",
          "fields": [
            "record_id",
            "status",
            "items (JSONB)",
            "filename",
            "content_type",
            "size",
            "content (BYTEA)"
          ]
        },
        {
          "name": "invoices, invoice_items & payments",
          "type": "Table",
          "fields": [
            "invoice_number",
            "total",
            "paid",
            "status",
            "price",
            "method",
            "idempotency_key",
            "void_reason"
          ]
        },
        {
          "name": "audit_logs, settings & notifications",
          "type": "Table",
          "fields": [
            "actor_id",
            "action",
            "entity_type",
            "outcome",
            "data (JSONB)",
            "message",
            "read"
          ]
        }
      ]
    },
    "technicalImplementation": [
      {
        "category": "Concurrency",
        "title": "Advisory Transaction Locking & Row-Level Schedule Serialization",
        "description": "Critical mutations in AppointmentService, ScheduleController, QueueController, MedicalController, BillingController, and ReminderJob invoke pg_advisory_xact_lock(81726011) combined with SELECT ... FOR UPDATE, preventing simultaneous last-slot overbooking and duplicate check-ins.",
        "badge": "Locking"
      },
      {
        "category": "Security",
        "title": "SHA-256 Opaque Sessions, Login Throttling & Magic-Byte Upload Checks",
        "description": "AuthController generates 32-byte SecureRandom bearer tokens whose SHA-256 digests are persisted in PostgreSQL, throttles 10 failed logins per 10 minutes via audit_logs, revokes sessions on role/password changes, and AttachmentController verifies PDF/PNG/JPEG file headers.",
        "badge": "Hardened Auth"
      },
      {
        "category": "Clinical Integrity",
        "title": "Immutable Finalization, Revision History & Append-Only Addenda",
        "description": "Draft saves snapshot prior JSONB payloads into record_revisions. Finalization requires all 13 clinical and vital fields, locks the chart against edits, and routes subsequent notes or prescription corrections through addenda and revision snapshots.",
        "badge": "EMR Audit"
      },
      {
        "category": "Financial Integrity",
        "title": "Tariff Snapshots & Idempotent Payment Ledger",
        "description": "Invoice items copy service name and price at creation so later catalog edits never mutate historical bills. Payments enforce unique idempotency_key deduplication, reject overpayments, and preserve VOID transactions with mandatory SYSADMIN reasons.",
        "badge": "Idempotency"
      }
    ],
    "primaryTechSpecs": {
      "programmingLanguage": "Java & TypeScript",
      "framework": "Spring Boot & Angular",
      "database": "PostgreSQL"
    },
    "architectureQuality": {
      "badges": [
        "RBAC Access Control",
        "Atomic Slot Locking",
        "Immutable Medical Records",
        "Idempotent Payment Ledger"
      ]
    }
