    "dataAnalyticsKeyFindings": [
      {
        "metricValue": "$41.03M",
        "metricLabel": "Realized Net Revenue",
        "title": "84.19% Gross-to-Net Revenue Realization",
        "description": "Out of $48.73M in gross ordered subtotal across 90,000 orders, 77,682 active orders generated $41.03M realized net revenue and $19.02M gross profit at a 46.37% margin.",
        "impactTag": "Commercial P&L"
      },
      {
        "metricValue": "$6.48M",
        "metricLabel": "Cancel & Return Leakage",
        "title": "Post-Checkout Leakage Exceeds Discounts by 5.3x",
        "description": "Cancelled orders ($3.07M, 6.49%) and returned orders ($3.41M, 7.79% order return rate) erode 13.64% of net ordered merchandise compared to $1.22M in promotional discounts.",
        "impactTag": "Revenue Leakage"
      },
      {
        "metricValue": "+20.97%",
        "metricLabel": "2026 YTD YoY Growth",
        "title": "Consistent Organic Expansion Across Equal YTD Windows",
        "description": "Apples-to-apples Jan–Sep net revenue grew +24.88% in 2025 ($10.28M) and +20.97% in 2026 ($12.44M) while gross margin stayed stable (46.25%–46.44%) and return rate fell to 7.41%.",
        "impactTag": "Growth Trend"
      },
      {
        "metricValue": "50.54%",
        "metricLabel": "Sizing & Description Returns",
        "title": "Fit and Expectation Mismatches Dominate Item Refunds",
        "description": "Wrong size (29.55%, $427.20K) and not as described (20.99%, $301.74K) account for over half of 8,000 documented return items ($1.46M refunds), whereas unit price shows no correlation (p = 0.7647).",
        "impactTag": "Return Risk"
      },
      {
        "metricValue": "40.75%",
        "metricLabel": "Footwear Gross Margin",
        "title": "Footwear Trails Top-Margin Categories by 7.3 Points",
        "description": "Footwear generates $4.11M in realized revenue at the lowest category margin (40.75%), trailing Backpacks (48.05%) and Navigation (48.03%), while discounts correlate negatively with margin (rho = -0.301).",
        "impactTag": "Margin Erosion"
      },
      {
        "metricValue": "72.19%",
        "metricLabel": "Top 20% SKU Revenue Share",
        "title": "Strong Catalog Concentration & Carrier Return Variance",
        "description": "The top 300 SKUs generate 72.19% of revenue, while carrier return rates vary significantly (p = 0.0216) led by Royal Mail (8.60%) and DPD (8.41%) vs USPS (7.39%).",
        "impactTag": "Logistics & Pareto"
      }
    ],
    "recommendationsAndConclusion": {
      "recommendations": [
        {
          "title": "Interactive Size Guides & PDP Content Audit",
          "action": "Deploy category-specific size charts, dimension comparisons, and high-resolution detail imagery across Backpacks, Footwear, Apparel, and Navigation to reduce wrong-size and expectation-gap returns (50.54% of cases) by 10–15%.",
          "priority": "HIGH"
        },
        {
          "title": "Pre-Q4 Carrier SLA Audit & Proactive Rerouting",
          "action": "Audit Royal Mail (8.60% return rate) and DPD (8.41%) delivery SLAs ahead of November–December peak volume (~2x normal demand) and trigger proactive delay alerts to curb late-arrival returns (p = 0.0245).",
          "priority": "HIGH"
        },
        {
          "title": "Discount Guardrails on Low-Margin Categories",
          "action": "Cap aggressive promotional discounting on Footwear (40.75% margin) given the negative discount-margin correlation (rho = -0.3010) and shift promotions toward higher-margin Backpacks and Accessories bundles.",
          "priority": "MEDIUM"
        },
        {
          "title": "Mandatory OMS Return-Reason Logging",
          "action": "Enforce itemized return-reason capture across all returned/refunded orders to close the 22.87% logging gap (1,482 orders missing from returns.csv) and enable accurate 90-day pilot tracking.",
          "priority": "STRATEGIC"
        }
      ],
      "conclusion": "Realized net revenue expanded +24.88% (2025) and +20.97% (2026) YTD with a stable 46.37% gross margin, yet $6.48M in cancellation and return leakage remains 5.3x larger than discount spend. Targeted PDP sizing fixes, pre-Q4 carrier SLA audits, and margin guardrails offer the highest profit recovery."
    },
