    "projectInfo": {
      "projectType": "Full-Stack Web Application",
      "developmentStatus": "Completed",
      "developmentYear": "2026",
      "platform": "Web (Desktop, Tablet, Mobile)",
      "projectCategory": "Web Development"
    },
    "projectBackground": "Organizations collecting customer, employee, and research feedback often face fragile form schemas, duplicate submissions under retries, and coarse access controls. SurveyHub solves this by isolating draft edits from immutable published versions while enforcing transactional response limits and role-scoped visibility.",
    "problemStatements": [
      {
        "title": "Schema Drift Corrupting Historical Answers",
        "description": "Editing a live survey's questions or options in place breaks alignment between older responses and current analytics aggregations.",
        "issueCode": "ISSUE_01"
      },
      {
        "title": "Race Conditions & Duplicate Submissions",
        "description": "Concurrent respondents hitting a response cap or retrying failed requests can exceed survey quotas or record duplicate entries.",
        "issueCode": "ISSUE_02"
      },
      {
        "title": "Coarse Multi-Team Access Control",
        "description": "Shared form tools often expose all workspace responses and export capabilities to every contributor regardless of role boundaries.",
        "issueCode": "ISSUE_03"
      },
      {
        "title": "Unvalidated File Uploads & CSV Formula Injection",
        "description": "Public respondent attachments and exported spreadsheets introduce security risks if MIME signatures and formula prefixes go unchecked.",
        "issueCode": "ISSUE_04"
      }
    ],
    "projectObjectives": [
      {
        "title": "Immutable Publication Snapshots",
        "description": "Separate mutable builder drafts from immutable published versions and bind every submitted response to its exact version snapshot.",
        "targetTag": "TARGET_01"
      },
      {
        "title": "Transactional Idempotency & Quota Enforcement",
        "description": "Guarantee exact response limits under parallel traffic and safe client retries via deterministic SHA-256 idempotency keys.",
        "targetTag": "TARGET_02"
      },
      {
        "title": "Granular Workspace RBAC",
        "description": "Enforce server-side Owner, Editor, and Analyst roles with independent publish, read, export, and per-survey assignment scopes.",
        "targetTag": "TARGET_03"
      },
      {
        "title": "Asynchronous Secure Tabular Exports",
        "description": "Offload CSV and OOXML XLSX generation to background jobs with formula-injection escaping and re-verified download permissions.",
        "targetTag": "TARGET_04"
      }
    ],
    "coreFeatures": [
      {
        "title": "Three-Pane Visual Survey Builder",
        "description": "Construct surveys with 9 question types (short text, paragraph, multiple choice, checkbox, dropdown, star rating, linear scale, date, and file upload), live ordering, draft preview, and optimistic revision locking.",
        "badge": "Authoring"
      },
      {
        "title": "Immutable Versioning & Conflict Guard",
        "description": "Draft edits increment survey revision numbers while publishing freezes an immutable version definition; respondents on stale versions receive a 409 reload prompt preserving local form inputs.",
        "badge": "Versioning"
      },
      {
        "title": "Idempotent Public Forms & Embeds",
        "description": "Deliver account-free respondent forms via public links or iframe embeds with active start/end schedules, response caps, and SHA-256 idempotency keys preventing duplicate writes.",
        "badge": "Collection"
      },
      {
        "title": "Timezone-Aware Analytics & Filtering",
        "description": "Aggregate response counts, daily/weekly/monthly trends, means, medians, and per-definition-hash answer distributions filtered cleanly within each workspace's configured timezone.",
        "badge": "Analytics"
      },
      {
        "title": "Background CSV & OOXML XLSX Exports",
        "description": "Generate UTF-8 BOM CSV files with formula apostrophe escaping and native multi-sheet-compatible OOXML XLSX archives asynchronously with permission re-checks on download.",
        "badge": "Reporting"
      },
      {
        "title": "Multi-Workspace RBAC & Admin Console",
        "description": "Manage isolated workspaces, email-verified invitations, survey-scoped Editor/Analyst permissions, and a global admin dashboard to monitor metrics and disable compromised accounts.",
        "badge": "Governance"
      }
    ],
