    "userFlow": {
      "summary": "Users authenticate into a scoped workspace, upload CSV or XLSX data for automated profiling, confirm schema mapping and cleaning to publish a Ready version, compose ECharts dashboards with cross-filters, share dashboards by role, and download PDF or XLSX exports.",
      "steps": [
        {
          "step": "01",
          "title": "Authenticate & Select Workspace",
          "description": "Users sign in or choose a demo role via session cookies and CSRF tokens, then switch between isolated workspaces via the X-Workspace-Id header.",
          "actorOrNode": "Auth / App Shell"
        },
        {
          "step": "02",
          "title": "Upload Dataset & Inspect Quality",
          "description": "Analysts upload CSV or XLSX files; the background worker parses headers, infers six column types, and computes missing, duplicate, and mismatch diagnostics.",
          "actorOrNode": "DataSources / Worker"
        },
        {
          "step": "03",
          "title": "Map Schema & Confirm Cleaning",
          "description": "Users preview sheet rows, adjust column types, simulate quality impact, and confirm deduplication, trimming, or null coercion to publish an immutable DatasetVersion.",
          "actorOrNode": "Cleaning Pipeline"
        },
        {
          "step": "04",
          "title": "Build Dashboard & Cross-Filter",
          "description": "Authors attach a Ready dataset, configure KPI, bar, line, area, pie, or pivot widgets via live backend previews, apply global filters, and save with optimistic locking.",
          "actorOrNode": "Dashboard Builder"
        },
        {
          "step": "05",
          "title": "Share by Role & Export Reports",
          "description": "Owners and Analysts share dashboards with teammates; Viewers explore temporary filters on saved widgets and queue asynchronous PDF or XLSX exports for 24-hour download.",
          "actorOrNode": "RBAC & Export Worker"
        }
      ]
    },
    "systemArchitecture": {
      "summary": "DataInsight decouples a Svelte and TypeScript frontend behind Nginx from a Gunicorn-served Django REST API, sharing PostgreSQL or SQLite persistence and a mounted media volume with a dedicated polling worker for ingestion, cleaning, and report exports.",
      "layers": [
        {
          "name": "Client Presentation Layer",
          "role": "Renders reactive workspace views, dashboard builder, filter bar, and ECharts visualizations in the browser.",
          "components": [
            "Svelte SPA",
            "TypeScript API Client",
            "ECharts Renderer",
            "Tailwind CSS UI"
          ]
        },
        {
          "name": "Reverse Proxy & Gateway Layer",
          "role": "Serves compiled static frontend assets, enforces security headers, and proxies /api requests to Django.",
          "components": [
            "Nginx Reverse Proxy",
            "Vite Dev Proxy",
            "Security Headers Middleware"
          ]
        },
        {
          "name": "Application & Analytics Layer",
          "role": "Enforces session/CSRF auth, workspace RBAC, schema validation, optimistic locking, and Python analytics queries.",
          "components": [
            "Django WSGI API",
            "Access Control Service",
            "Analytics Query Engine",
            "Audit Logger"
          ]
        },
        {
          "name": "Background Worker & Export Layer",
          "role": "Polls queued jobs with atomic compare-and-set claiming to parse spreadsheets, clean versions, and render reports.",
          "components": [
            "Durable Job Runner",
            "CSV/XLSX Parser",
            "ReportLab PDF Builder",
            "OpenPyXL Exporter"
          ]
        },
        {
          "name": "Persistence & Storage Layer",
          "role": "Stores relational metadata, versioned JSON dataset rows, job states, and raw/exported files.",
          "components": [
            "PostgreSQL",
            "SQLite",
            "DatasetRecords Table",
            "Media Storage Volume"
          ]
        }
      ]
    },
    "databaseDataFlow": {
      "type": "Database Schema / ERD",
      "summary": "Relational models isolate workspaces, memberships, datasets, immutable versions, dashboards, shares, durable jobs, and audit logs, while DatasetRecords persists parsed and cleaned JSON rows in database storage.",
      "entitiesOrPipelines": [
        {
          "name": "Workspace & Member",
          "type": "Table",
          "fields": [
            "id",
            "name",
            "owner_id",
            "role",
            "joined_at",
            "unique_workspace_member"
          ]
        },
        {
          "name": "Dataset, DatasetVersion & DatasetRecords",
          "type": "Table",
          "fields": [
            "id",
            "workspace_id",
            "source_key",
            "data_key",
            "schema",
            "quality",
            "row_count",
            "status",
            "number",
            "rows"
          ]
        },
        {
          "name": "Dashboard & Share",
          "type": "Table",
          "fields": [
            "id",
            "workspace_id",
            "dataset_id",
            "owner_id",
            "name",
            "config",
            "updated_at",
            "unique_dashboard_share"
          ]
        },
        {
          "name": "Job",
          "type": "Table",
          "fields": [
            "id",
            "workspace_id",
            "requested_by_id",
            "kind",
            "dataset_id",
            "dashboard_id",
            "payload",
            "status",
            "file_key"
          ]
        },
        {
          "name": "AuditLog, Invitation & LoginAttempt",
          "type": "Table",
          "fields": [
            "workspace_id",
            "actor_id",
            "action",
            "resource",
            "metadata",
            "token",
            "email",
            "key",
            "count"
          ]
        }
      ]
    },
    "technicalImplementation": [
      {
        "category": "Concurrency & Job Reliability",
        "title": "Atomic Compare-and-Set Worker Claiming & Partial Constraints",
        "description": "The runworker command claims Queued jobs via atomic conditional updates, enforces a partial unique constraint (one_active_job_per_dataset) on Queued/Processing states, and requeues jobs stalled over 30 minutes.",
        "badge": "Job Queue"
      },
      {
        "category": "Security & Access Control",
        "title": "Saved-Widget Viewer Enforcement & Rate-Limited Auth",
        "description": "Viewers querying /api/analytics/query must reference a valid dashboard_id and saved widget_id so injected query payloads are ignored; LoginAttempt enforces a 12-attempt per 15-minute rate limit alongside HttpOnly sessions and CSRF checks.",
        "badge": "RBAC & Auth"
      },
      {
        "category": "Data Integrity & Optimistic Locking",
        "title": "Immutable Dataset Versions & Dashboard Conflict Detection",
        "description": "Cleaning runs inside database transactions creating incremental DatasetVersion and DatasetRecords rows without overwriting originals, while PATCH /api/dashboards/{id} validates updated_at to block concurrent overwrites.",
        "badge": "ACID & Versioning"
      },
      {
        "category": "Analytics & Export Safety",
        "title": "Schema-Bound Query Execution & Formula-Injection Neutralization",
        "description": "Analytics queries validate every column, aggregation, and filter against Dataset.schema with an 8-second and 10,000-group ceiling, while OpenPyXL exports escape leading =, +, -, and @ characters and enforce 24-hour download expiry.",
        "badge": "Query & Export"
      }
    ],
